      {
        id: 'pride-prejudice',
        title: 'Pride and Prejudice',
        author: 'Jane Austen',
        youtubeUrl: 'https://www.youtube.com/watch?v=ZhxqauL9WbM',
        catalogueMatches: ['Pride and Prejudice'],
        availabilityType: 'full_public_domain',
