function lilithTitleFromChapterOnlyName(base: string): string | undefined {
  const match = base.match(/^\s*chapter\s+[ivxlcdm\d]+\s*[:\-_.]\s*(.+?)\s*$/i);
  if (!match) return undefined;
  const chapterTitle = match[1]?.trim();
